namespace App \ EventSubscriber ; use Symfony \ Component \ EventDispatcher \ EventSubscriberInterface ; use Symfony \ Component \ HttpKernel \ Event \ ExceptionEvent ; class ExceptionSubscriber implements EventSubscriberInterface
{ public static function getSubscribedEvents () : array { // return the subscribed events, their methods and priorities return [
