use Symfony \ Component \ HttpFoundation \ File \ File ; use Symfony \ Component \ HttpFoundation \ ResponseHeaderBag ; // ...
public function download () : BinaryFileResponse
{ // load the file from the filesystem $ file = new File ( '/path/to/some_file.pdf' ); return $ this -> file ( $ file ); // rename the downloaded file return $ this -> file ( $ file , 'custom_name.pdf' ); // display the file contents in the browser instead of downloading it return $ this -> file ( 'invoice_3241.pdf' , 'my_invoice.pdf' , ResponseHeaderBag:: DISPOSITION_INLINE );
