    ]);
} catch (PartialDenormalizationException $ e ) { $ violations = new ConstraintViolationList (); /** @var NotNormalizableValueException $exception */ foreach ( $ e -> getErrors () as $ exception ) { $ message = sprintf ( 'The type must be one of "%s" ("%s" given).' , implode ( ', ' , $ exception -> getExpectedTypes ()), $ exception -> getCurrentType ()); $ parameters = []; if ( $ exception -> canUseMessageForUser ()) { $ parameters [ 'hint' ] = $ exception -> getMessage ();
        } $ violations -> add ( new ConstraintViolation ( $ message , '' , $ parameters , null , $ exception -> getPath (), null ));
    } // ... return violation list to the user }
```

```
