$ jsonData = '{"age":39,"name":"Jane Doe"}' ; $ person = $ serializer -> deserialize ( $ jsonData , Person:: class , 'json' , [
    AbstractNormalizer:: DEFAULT_CONSTRUCTOR_ARGUMENTS => [
